 public class Component:Object {public GameObject gameObject;public Transform transform{get{return gameObject.transform;}}public T GetComponent<T>() where T:class{return gameObject.GetComponent<T>();}public T[] GetComponentsInChildren<T>(bool a){return new T[0];}}
 public class MonoBehaviour:Component{}public class Transform:Component {public string name;public Transform parent;public Transform Find(string n){return null;}public void SetParent(Transform p,bool b){parent=p;}public void SetAsFirstSibling(){}public void SetAsLastSibling(){}}
 public class RectTransform:Transform{}public class GameObject:Object {Dictionary<Type,object> components=new Dictionary<Type,object>();public string name;public bool activeSelf,activeInHierarchy=true;public Transform transform;public GameObject(string n,params Type[] types){name=n;transform=new RectTransform{gameObject=this};foreach(var t in types)if(t!=typeof(RectTransform))AddComponent(t);}object AddComponent(Type t){var v=Activator.CreateInstance(t);if(v is Component)((Component)v).gameObject=this;components[t]=v;return v;}public T AddComponent<T>() where T:new(){return (T)AddComponent(typeof(T));}public T GetComponent<T>() where T:class{object v;return components.TryGetValue(typeof(T),out v)?v as T:null;}public void SetActive(bool b){activeSelf=b;}}
 public static class Resources{public static T Load<T>(string p) where T:class{return new GameObject("prefab") as T;}}public static class Debug{public static void LogWarning(object e){}}public static class Time{public static float unscaledTime;}public enum HorizontalWrapMode{Wrap}public enum VerticalWrapMode{Truncate}
