class CurrencyPanelTests {
 static int count;static void Check(bool b,string n){if(!b)throw new Exception(n);count++;}static object Field(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static void Call(object o,string n){o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,null);}
 static void Main(){var panel=new UnityEngine.GameObject("currency").AddComponent<GodCurrencyEditorPanel>();var window=new UnityEngine.GameObject("kingdom").AddComponent<KingdomWindow>();panel.Bind(window);Call(panel,"OnEnable");var input=(UnityEngine.UI.InputField)Field(panel,"amountInput");var rows=(List<KeyValueField>)Field(panel,"rows");Check(rows.Count==9&&!rows[8].gameObject.activeSelf,"compact wallet with exchange collapsed");input.text="54321";Call(panel,"Refresh");Check(NativeLifecycle.lastAmount==0&&rows[2].value.text=="10 金币","typing and refresh never execute or replace balance");rows[4].on_click_value();Check(NativeLifecycle.lastAmount==54321&&NativeLifecycle.lastOperation==CurrencyScope.Operation.MintGold,"issue selected gold using custom amount");rows[5].on_click_value();Check(NativeLifecycle.lastOperation==CurrencyScope.Operation.BurnGold,"recover selected gold");rows[1].on_click_value();Check(rows[2].value.text=="20 GOD"&&input.text=="54321","currency switch changes balance without editing quantity");rows[4].on_click_value();Check(NativeLifecycle.lastOperation==CurrencyScope.Operation.MintGod,"issue selected GOD");rows[5].on_click_value();Check(NativeLifecycle.lastOperation==CurrencyScope.Operation.BurnGod,"recover selected GOD");input.text="0";rows[4].on_click_value();Check(NativeLifecycle.lastOperation==CurrencyScope.Operation.BurnGod,"invalid amount cannot execute");input.text="12";rows[7].on_click_value();Check(rows[8].gameObject.activeSelf,"exchange expands on demand");rows[8].on_click_value();Check(NativeLifecycle.lastOperation==CurrencyScope.Operation.GodToGold&&NativeLifecycle.lastAmount==12,"exchange spends selected currency and shared custom amount");rows[7].on_click_value();Check(!rows[8].gameObject.activeSelf,"exchange collapses again");window.kingdom=new Kingdom();Call(panel,"Refresh");Check(input.text=="1000"&&rows[2].value.text=="10 金币"&&!rows[8].gameObject.activeSelf,"switch target resets draft and stays on selected wallet only");Check(rows.TrueForAll(r=>!r.name_text.text.Contains("拨")&&!r.name_text.text.Contains("上缴")&&!r.name_text.text.Contains("存档")&&!r.name_text.text.Contains("汇率")&&!r.name_text.text.Contains("投入")&&!r.name_text.text.Contains("范围")),"wallet contains no unrelated controls");var law=new UnityEngine.GameObject("rate").AddComponent<GodWorldRatePanel>();Call(law,"OnEnable");var rateInput=(UnityEngine.UI.InputField)Field(law,"input");rateInput.text="2.5";Call(law,"Save");Check(GodWorldRuntime.GetRate()==2.5,"world law remains the exchange rate editor");double n;Check(!CurrencyInput.TryRate("NaN",out n)&&!CurrencyInput.TryRate("0",out n)&&!CurrencyInput.TryAmount("2147483648",out n),"invalid rates and quantities rejected");Console.WriteLine(count+" currency panel checks passed");}
}
